package io.tornado.strategies;
import io.tornado.persistence.*;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.mock;
class StrategyProfileResolverTest{@Test void coinSpecificProfileOverridesGlobalAndMissingEvidenceUsesDeterministicFallback(){Coin coin=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(coin,"id",1L);var global=StrategyHorizonProfile.selected(null,ProfileScope.GLOBAL,"EMA_20",1,3600,"15m","20",2,new StrategyHorizonProfile.Evidence(),"global",Instant.now());var specific=StrategyHorizonProfile.selected(coin,ProfileScope.COIN_SPECIFIC,"EMA_20",1,3600,"30m","10",1,new StrategyHorizonProfile.Evidence(),"override",Instant.now());var resolved=new StrategyProfileResolver(mock(StrategyHorizonProfileRepository.class)).resolve(List.of(coin),List.of(global,specific)).get(1L);var ema=resolved.stream().filter(p->p.getStrategyCode().equals("EMA_20")&&p.getPredictionHorizonSeconds()==3600).findFirst().orElseThrow();var rsi=resolved.stream().filter(p->p.getStrategyCode().equals("RSI_14")&&p.getPredictionHorizonSeconds()==86400).findFirst().orElseThrow();assertThat(ema.getAnalysisTimeframe()).isEqualTo("30m");assertThat(ema.getProfileScope()).isEqualTo(ProfileScope.COIN_SPECIFIC);assertThat(rsi.getAnalysisTimeframe()).isEqualTo("4h");assertThat(rsi.getSelectionSource()).isEqualTo(ProfileSelectionSource.FALLBACK);}}
